# MES version of fig_h_strat_hist.py generated by scratch make_figs_mes.py (PREREG_MESCKPT); reads the *_mes data files; writes fig_h_strat_hist_mes.pdf
"""Hypothesis figure H-a: the gain of MSCA + MES over MSCA by the training history length of the test user.

Hypothesis: the self-message share of a training score (fig:selfmsg (a)) and the BPR weight it removes are largest for
users with short histories, so MES, which trains held-out positives without their self-message, should help them most.
Data: tables/hyp_strat_hist.csv (tables/src/collect_hyp_strat.py; MSCA and MSCA + MES best-valid checkpoints, seeds 1-5,
one run per seed: P04_listana reruns for Baby / Pantry / Scientific, Table I runs of P04_sports for Sports).
  (a) relative test Recall@20 gain 100 (R_x - R_n) / R_n of the users in each history bin (d_u <= 3, 4-7, 8-15, >= 16,
      the bins of fig:selfmsg (a)), R_x / R_n = mean Recall@20 of the bin for MSCA + MES / MSCA on the same seed.
      Marker = mean over seeds 1-5, bar = range over the seeds.
  (b) the same for NDCG@20.
  The percentage under each tick label = share of the test users in the bin, mean over the four datasets. A mean outside
  the y range (Scientific, d_u >= 16, 150 users) is drawn at the axis edge with its value printed; its seed range is clipped.
Usage: python -s figures/src/fig_h_strat_hist.py
"""
import csv
import statistics as st

from style import C_OURS, COL, TABLES, plt, save, setup

SRC = TABLES / 'src' / 'data' / 'hyp_strat_hist_mes.csv'
DATASETS = [('baby', 'Baby'), ('pantry', 'Pantry'), ('scientific', 'Scientific'), ('sports', 'Sports')]
BINS = [('le3', r'$\leq$3'), ('4to7', '4–7'), ('8to15', '8–15'), ('ge16', r'$\geq$16')]
STYLE = {'baby': ('o', '-'), 'pantry': ('s', '--'), 'scientific': ('^', ':'), 'sports': ('D', (0, (3, 1, 1, 1)))}
SEEDS = ['1', '2', '3', '4', '5']
YLIM = (-10, 11)   # Scientific >= 16 (150 users) leaves the axis: its mean is printed next to the edge marker


def main():
    setup()
    rows = list(csv.DictReader(open(SRC, newline='', encoding='utf-8')))
    v = {(r['dataset'], r['arm'], r['seed'], r['bin']): r for r in rows}
    fig, axes = plt.subplots(1, 2, figsize=(COL, 1.6), sharey=True)
    for ax, (met, title) in zip(axes, (('recall20', '(a) Recall@20'), ('ndcg20', '(b) NDCG@20'))):
        for k, (ds, D) in enumerate(DATASETS):
            mk, ls = STYLE[ds]
            xs = [i + (k - (len(DATASETS) - 1) / 2) * 0.09 for i in range(len(BINS))]
            g = [[100 * (float(v[(ds, 'mes', s, b)][met]) / float(v[(ds, 'native', s, b)][met]) - 1) for s in SEEDS]
                 for b, _ in BINS]
            m = [st.mean(x) for x in g]
            mc = [min(max(a, YLIM[0] + 0.8), YLIM[1] - 0.8) for a in m]          # off-scale means drawn at the edge
            ax.errorbar(xs, mc, yerr=[[max(a - min(x), 0) for a, x in zip(mc, g)], [max(max(x) - a, 0) for a, x in zip(mc, g)]],
                        color=C_OURS, marker=mk, ms=3, ls=ls, lw=0.8, elinewidth=0.6, capsize=1.2, mfc='white', mew=0.7,
                        label=D)
            for x, a, c in zip(xs, m, mc):
                if a != c:
                    ax.annotate(f'{a:.1f}'.replace('-', '−'), (x, c), xytext=(-3, 0), textcoords='offset points', ha='right', va='center',
                                fontsize=5.2, color=C_OURS)
        ax.axhline(0, color='#888888', lw=0.5, zorder=0)
        ax.set_xticks(range(len(BINS)))
        share = [st.mean(100 * int(v[(ds, 'native', '1', b)]['n_users']) / int(v[(ds, 'native', '1', 'all')]['n_users'])
                     for ds, _ in DATASETS) for b, _ in BINS]
        ax.set_xticklabels([f'{lab}\n{s:.0f}%' for (_, lab), s in zip(BINS, share)])
        ax.set_xlabel('History length (user share)')
        ax.set_title(title, pad=3)
        ax.set_ylim(*YLIM)
        ax.set_xlim(-0.45, len(BINS) - 0.55)
        ax.grid(axis='y', lw=0.3, alpha=0.5)
        ax.set_axisbelow(True)
    axes[0].set_ylabel('Gain over MSCA (%)')
    hs = [plt.Line2D([], [], color=C_OURS, marker=STYLE[ds][0], ls=STYLE[ds][1], ms=3, lw=0.8, mfc='white', mew=0.7)
          for ds, _ in DATASETS]
    fig.legend(hs, [D for _, D in DATASETS], loc='upper center', ncol=4, frameon=False, handlelength=2.0,
               bbox_to_anchor=(0.5, 1.07), handletextpad=0.4, columnspacing=1.0, fontsize=6.2)
    fig.tight_layout(w_pad=0.8)
    save(fig, 'fig_h_strat_hist_mes', [SRC])


if __name__ == '__main__':
    main()
